<template><div class="app-container usage"><h2>用量统计</h2><p>按用户与模型汇总每次供应商调用，包含失败后的恢复尝试。</p><el-form inline @submit.prevent="search"><el-form-item label="日期"><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" range-separator="至"/></el-form-item><el-form-item label="用户 ID"><el-input v-model="userId" clearable inputmode="numeric" style="width:120px"/></el-form-item><el-form-item label="模型 ID"><el-input v-model="modelId" clearable inputmode="numeric" style="width:120px"/></el-form-item><el-form-item><el-button type="primary" :loading="loading" @click="search">查询</el-button></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert title="成本与点数分别记账。点数预占仅统计已产生调用的份额，完整账户余额见创作者详情。" type="info" :closable="false"/><el-table v-loading="loading" :data="rows" empty-text="此日期范围暂无调用"><el-table-column prop="userId" label="用户 ID" width="110"/><el-table-column prop="modelId" label="模型 ID" width="100"/><el-table-column prop="model" label="调用模型" min-width="180"/><el-table-column prop="calls" label="调用次数" min-width="100"/><el-table-column label="估算成本 / 元" min-width="145"><template #default="{row}">{{ formatMicros(row.chargedMicros) }}</template></el-table-column><el-table-column label="成本预占 / 元" min-width="145"><template #default="{row}">{{ formatMicros(row.reservedMicros) }}</template></el-table-column><el-table-column prop="pointsSpent" label="已用点数" min-width="110"/><el-table-column prop="pointsHeld" label="调用预占点数" min-width="130"/></el-table><pagination v-show="total>0" v-model:page="page" v-model:limit="size" :total="total" @pagination="load"/></div></template>
<script setup>
import{onMounted,onBeforeUnmount,ref}from'vue'
import{adminList}from'@/api/pod/admin'
import{formatMicros,localDate}from'@/utils/pod-admin'
const dates=ref([localDate(new Date(Date.now()-6*86400000)),localDate(new Date())]),userId=ref(''),modelId=ref(''),rows=ref([]),total=ref(0),page=ref(1),size=ref(10),loading=ref(false),error=ref('');let sequence=0
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const r=await adminList('usage',{beginDate:dates.value?.[0],endDate:dates.value?.[1],userId:userId.value,modelId:modelId.value,pageNum:page.value,pageSize:size.value});if(seq===sequence){rows.value=r.rows;total.value=r.total}}catch(e){if(seq===sequence)error.value=e.message}finally{if(seq===sequence)loading.value=false}}
function search(){page.value=1;load()}onMounted(load);onBeforeUnmount(()=>++sequence)
</script><style scoped>.usage p{color:var(--el-text-color-secondary)}.usage :deep(.el-alert){margin:12px 0}.usage :deep(.el-form-item){margin-bottom:12px}</style>
